'use strict';
const scanState={},scanVenues=['Popdex','Arcus','Variational'];let scanRunning=false,scanToken=0,lastScanStart=0;
const priorShowScan=show;show=function(p){priorShowScan(p);if(p==='auto')paintScans();};
function paintScans(){if(page==='auto'){$('source-pill').textContent='● Automatic research';$('notice').textContent='Shortlists use real exchange data. A high score is a research priority, not a trade recommendation. Stale, closed-session and incomplete-cost pairs cannot qualify.';}
 $('scan-boards').innerHTML=scanVenues.map(v=>{const state=scanState[v];if(!state)return `<article class="panel padded scan-board"><h2>${v}</h2><p>Waiting for scan.</p></article>`;const stale=state.time&&Date.now()-state.time>600000;const valid=state.results?.filter(r=>r.eligible)||[],research=state.results?.filter(r=>!r.eligible)||[];let body='';if(v==='Variational'){body=(state.watch||[]).slice(0,8).map(p=>`<tr><td>${esc(p.a.symbol)} / ${esc(p.b.symbol)}</td><td>${money(Math.min(p.a.volume||0,p.b.volume||0))}</td><td>${fmt(p.a.spread)} / ${fmt(p.b.spread)}</td><td>History unavailable · no signal</td></tr>`).join('');body=`<p>Liquidity watchlist only, sorted by the smaller leg’s 24h volume. No statistical ranking.</p><div class="table-wrap"><table><thead><tr><th>PAIR</th><th>MIN LEG VOLUME</th><th>SPREADS BPS</th><th>STATUS</th></tr></thead><tbody>${body||'<tr><td colspan="4">No watchlist available.</td></tr>'}</tbody></table></div>`;}else{const ranked=[...valid,...research].slice(0,12);body=`<p>${state.status==='Scanning'?'Fetching histories and evaluating pairs…':valid.length?'Pairs passing research filters: '+valid.length:'No pairs pass every filter right now.'} ${v==='Arcus'?'Oracle-price research; execution costs incomplete.':''}</p><div class="table-wrap"><table><thead><tr><th>PAIR / RESEARCH SCORE</th><th>Z / 15m Z</th><th>CORR. / HALF-LIFE</th><th>MOVE / COST BPS</th><th>STATUS & REASONS</th><th></th></tr></thead><tbody>${ranked.map(r=>`<tr><td><strong>${esc(r.a.symbol)} / ${esc(r.b.symbol)}</strong><span class="pair-sub">${esc(r.group)} · ${r.score===null?'Unscored':r.score+'/100'}</span></td><td>${fmt(r.z)} / ${fmt(r.confirm)}</td><td>${fmt(r.corr)} / ${fmt(r.half,0)}m</td><td>${fmt(r.edge)} / ${fmt(r.cost)}</td><td class="scan-reasons"><strong>${stale?'Stale scan':r.setup?'Divergence to review':r.eligible?'Passes research filters':'Research only'}</strong><span class="pair-sub">${esc(r.reasons.join(' · ')||'Filters passed; no guaranteed opportunity')}</span></td><td><button class="secondary" data-scan-venue="${v}" data-scan-a="${esc(r.a.id)}" data-scan-b="${esc(r.b.id)}" ${!r.rows?.length?'disabled':''}>Inspect</button></td></tr>`).join('')||'<tr><td colspan="6">No ranked pairs available.</td></tr>'}</tbody></table></div>`;}
 return `<article class="panel padded scan-board"><h2>${v} <span class="pill">${esc(state.status||'')}</span></h2><small>${state.time?'Completed '+date(state.time)+' UTC · '+age(state.time)+' ago':''}${stale?' · STALE':''} ${state.coverage||''}</small>${state.error?'<p class="feed-bad">'+esc(state.error)+'</p>':''}${body}</article>`;}).join('');}
async function runScan(){if(scanRunning)return;if(Date.now()-lastScanStart<60000){toast('Please allow one minute between scans.');return;}scanRunning=true;lastScanStart=Date.now();const token=++scanToken,slip=+$('scan-slippage').value;if(!Number.isFinite(slip)||slip<0||slip>100){scanRunning=false;toast('Slippage must be between 0 and 100 bps.');return;}$('scan-now').disabled=true;$('stop-scan').disabled=false;
 try{for(const v of scanVenues){if(token!==scanToken)break;scanState[v]={status:'Scanning',results:[]};paintScans();$('scan-progress').textContent=v+': loading current instruments…';try{const snapshot=await MarketFeeds.markets(v);if(token!==scanToken)break;feedCache[v]=snapshot;const u=PairScan.universe(snapshot.rows),candidates=PairScan.pairs(u.rows);scanState[v].coverage=`${u.rows.length}/${u.eligible} supported eligible instruments · ${candidates.length} related pairs`;
 if(v==='Variational'){scanState[v]={...scanState[v],status:'Snapshot watchlist',time:Date.now(),watch:candidates.sort((a,b)=>Math.min(b.a.volume||0,b.b.volume||0)-Math.min(a.a.volume||0,a.b.volume||0))};paintScans();continue;}
 const histories=new Map(),errors=[];for(let i=0;i<u.rows.length;i++){if(token!==scanToken)break;const market=u.rows[i];$('scan-progress').textContent=`${v}: ${i+1}/${u.rows.length} histories · ${market.symbol}`;try{histories.set(market.id,await MarketFeeds.history(v,market.symbol));}catch(e){errors.push(market.symbol+': '+e.message);if(/Rate limited/.test(e.message))break;}await new Promise(r=>setTimeout(r,350));}
 if(token!==scanToken){scanState[v].status='Stopped';break;}
 const results=candidates.filter(p=>histories.has(p.a.id)&&histories.has(p.b.id)).map(p=>PairScan.analyze(p,MarketFeeds.align(histories.get(p.a.id),histories.get(p.b.id)),PairEngine,Date.now(),slip)).sort((a,b)=>Number(b.eligible)-Number(a.eligible)||(b.score??-1)-(a.score??-1));scanState[v]={...scanState[v],status:errors.length?'Partial scan':'Complete',results,time:Date.now(),error:errors.length?errors.length+' histories failed. '+errors.slice(0,2).join(' · '):null};paintScans();
 }catch(e){scanState[v]={status:'Unavailable',error:e.message,results:[]};paintScans();}}}finally{scanRunning=false;$('scan-now').disabled=false;$('stop-scan').disabled=true;$('scan-progress').textContent=token!==scanToken?'Scan stopped. Completed venue results are retained.':'Scan finished. Automatic refresh runs every five minutes while this tab is visible.';paintScans();}}
$('scan-now').onclick=runScan;$('stop-scan').onclick=()=>{scanToken++;$('scan-progress').textContent='Stopping after the current request…';};
$('scan-boards').onclick=e=>{const button=e.target.closest('[data-scan-venue]');if(!button)return;const v=button.dataset.scanVenue,r=scanState[v].results.find(r=>r.a.id===button.dataset.scanA&&r.b.id===button.dataset.scanB);if(!r?.rows.length)return;const item={a:r.a.id,b:r.b.id,rows:r.rows,venue:v,kind:v==='Arcus'?'Arcus oracle-price history':'Popdex market-candle history',sector:'Auto scan · '+r.group,demo:false,connected:true};const index=imported.findIndex(p=>p.venue===v&&p.a===item.a&&p.b===item.b);if(index<0)imported.push(item);else imported[index]=item;venue=v;selected=list().indexOf(item);document.querySelectorAll('[data-venue]').forEach(b=>b.classList.toggle('selected',b.dataset.venue===v));resetResult();render();show('scanner');};
setInterval(()=>{if(page==='auto')paintScans();if($('scan-repeat').checked&&!document.hidden&&Date.now()-lastScanStart>=300000)runScan();},15000);
show('auto');runScan();
document.querySelectorAll('[data-venue]').forEach(b=>b.addEventListener('click',()=>{if(page==='auto')paintScans();}));
